        /// <summary>Evaluates readiness for a request (pure; feed it the request facts).</summary>
        internal static HttpsReadiness Evaluate(bool requestIsHttps, Classification classification, NetworkSettings settings)
        {
            var fix = Capabilities.ProviderOf(CapabilityNames.Https);
            if (requestIsHttps || classification.ForwardedProtoHttps)
            {
                return new HttpsReadiness(HttpsState.Ready, "Served over HTTPS.", false, null);
            }

            if (classification.ViaProxy && !classification.ProxyTrusted)
            {
                return new HttpsReadiness(
                    HttpsState.Unverified,
                    "A proxy is in front of Jellyfin but isn't listed under Known proxies, so the original scheme can't be read.",
                    fix != null,
                    fix);
            }

            var detail = settings.EnableHttps
                ? "HTTPS is enabled in Jellyfin, but this page was loaded over plain http."
                : "Jellyfin is served over plain http.";
            return new HttpsReadiness(HttpsState.NotConfigured, detail, fix != null, fix);
        }

